//! The typed verbs: thin wrappers over [`Client::unary`] and
//! [`Client::server_stream`] over the generated `pb::` types.
//!
//! The RPC name is the method string on the wire; the request type is the
//! generated one, so a field added to `control.proto` and regenerated by
//! `make proto` is usable here without touching this file.

use std::time::Duration;

use crate::{pb, Client, Error, Streaming};

impl Client {
    /// One page of a conversation's transcript. Paging is `limit` + `before`:
    /// ask for the newest N, then keep asking with `before` set to the oldest
    /// timestamp you already hold.
    pub async fn get_history(
        &self,
        req: &pb::GetHistoryRequest,
    ) -> Result<pb::GetHistoryResponse, Error> {
        self.unary("GetHistory", req).await
    }

    /// One open of the daemon's event feed. A quiet stream ends with
    /// [`Error::is_idle`] and nothing re-opens it; [`Client::follow_events`]
    /// is the feed that resumes itself.
    pub async fn stream_events(
        &self,
        req: &pb::StreamEventsRequest,
        idle: Duration,
    ) -> Result<Streaming<pb::Event>, Error> {
        self.server_stream("StreamEvents", req, idle).await
    }

    pub async fn send(&self, req: &pb::SendRequest) -> Result<pb::SendResponse, Error> {
        self.unary("Send", req).await
    }

    pub async fn spawn(&self, req: &pb::SpawnRequest) -> Result<pb::SpawnResponse, Error> {
        self.unary("Spawn", req).await
    }

    /// Create a tag on a node, or move an existing one, and answer the stored
    /// row. A tag is a named, scoped handle to a node: naming it is the grant
    /// to fork from it, and `scope` says who holds it — lineage (the default)
    /// for the source's subtree and its ancestors, tree for everything under
    /// the tagger's top-level ancestor, owner for every agent of the owner.
    /// Anyone who can read a node may tag it; only the tag's creator, that
    /// creator's ancestors or a user credential may move or untag it.
    ///
    /// With `tag_id` empty this CREATES: `name` (1–64 of `[a-z0-9._-]`,
    /// starting with a letter or digit) names the node `child_id` + `cursor`
    /// points at (`m:<ordinal>`, or `m:<ordinal>.<n>`; empty means the last
    /// completed turn). A name already live in that scope is `already_exists`;
    /// `replace` tombstones the holder first and needs a user credential.
    ///
    /// With `tag_id` set this MOVES it: `expect_node_id` is required and must
    /// be the node the tag currently points at (compare-and-swap), while
    /// `name`, `scope` and `replace` must be unset. A stale expectation is
    /// `failed_precondition` — re-read the tag and retry. Every move appends a
    /// row, so a tag's history is never overwritten.
    pub async fn tag(&self, req: &pb::TagRequest) -> Result<pb::TagResponse, Error> {
        self.unary("Tag", req).await
    }

    /// Tombstone a tag's live row — the tag is revoked; nothing it pointed at
    /// is deleted. Only the tag's creator, that creator's ancestors or a user
    /// credential may untag it (`permission_denied`). An unknown tag id and
    /// another owner's look the same: `not_found`.
    pub async fn untag(&self, req: &pb::UntagRequest) -> Result<pb::UntagResponse, Error> {
        self.unary("Untag", req).await
    }

    /// The tags visible to the caller, nearest scope first (lineage, then tree,
    /// then owner), narrowed by `name_prefix`; `limit` 0 is the daemon's
    /// default of 50 (anything above 500 is clamped). With `tag_id` set the
    /// answer is that one tag's whole history, oldest first. Only the
    /// connection owner's tags are ever answered, so an unknown tag id and a
    /// foreign one look the same: `not_found`.
    pub async fn list_tags(
        &self,
        req: &pb::ListTagsRequest,
    ) -> Result<pb::ListTagsResponse, Error> {
        self.unary("ListTags", req).await
    }

    pub async fn get_child(
        &self,
        req: &pb::GetChildRequest,
    ) -> Result<pb::GetChildResponse, Error> {
        self.unary("GetChild", req).await
    }

    pub async fn list_children(
        &self,
        req: &pb::ListChildrenRequest,
    ) -> Result<pb::ListChildrenResponse, Error> {
        self.unary("ListChildren", req).await
    }

    pub async fn kill(&self, req: &pb::KillRequest) -> Result<pb::KillResponse, Error> {
        self.unary("Kill", req).await
    }

    pub async fn close(&self, req: &pb::CloseRequest) -> Result<pb::CloseResponse, Error> {
        self.unary("Close", req).await
    }

    pub async fn resume(&self, req: &pb::ResumeRequest) -> Result<pb::ResumeResponse, Error> {
        self.unary("Resume", req).await
    }

    pub async fn rename(&self, req: &pb::RenameRequest) -> Result<pb::RenameResponse, Error> {
        self.unary("Rename", req).await
    }

    pub async fn set_budget(
        &self,
        req: &pb::SetBudgetRequest,
    ) -> Result<pb::SetBudgetResponse, Error> {
        self.unary("SetBudget", req).await
    }

    pub async fn list_presets(
        &self,
        req: &pb::ListPresetsRequest,
    ) -> Result<pb::ListPresetsResponse, Error> {
        self.unary("ListPresets", req).await
    }

    pub async fn list_models(
        &self,
        req: &pb::ListModelsRequest,
    ) -> Result<pb::ListModelsResponse, Error> {
        self.unary("ListModels", req).await
    }

    /// The calling connection owner's model aliases, ordered by name. An
    /// alias is a slash-free model name the owner resolves through: `ds`
    /// means whatever [`Client::put_model_alias`] stored for it. Strictly per
    /// owner — no daemon-wide or fallback layer.
    pub async fn list_model_aliases(
        &self,
        req: &pb::ListModelAliasesRequest,
    ) -> Result<pb::ListModelAliasesResponse, Error> {
        self.unary("ListModelAliases", req).await
    }

    /// Create or replace one alias of the calling connection's owner
    /// (`created_at` survives a replace). `name` is `^[a-z0-9][a-z0-9._-]*$`
    /// — no `/`, no `[`; `target` is a model string whose base names a
    /// provider (`openrouter/~deepseek/...`), so an alias never chains to
    /// another alias. Neither is resolved against the catalog at put: a bad
    /// name or target is `invalid_argument`. Writing needs a user credential
    /// or the local socket — a child credential is `permission_denied`.
    pub async fn put_model_alias(
        &self,
        req: &pb::PutModelAliasRequest,
    ) -> Result<pb::PutModelAliasResponse, Error> {
        self.unary("PutModelAlias", req).await
    }

    /// Remove one of the calling owner's aliases. `not_found` when the owner
    /// has no alias by that name; needs a user credential or the local
    /// socket, like [`Client::put_model_alias`].
    pub async fn delete_model_alias(
        &self,
        req: &pb::DeleteModelAliasRequest,
    ) -> Result<pb::DeleteModelAliasResponse, Error> {
        self.unary("DeleteModelAlias", req).await
    }

    pub async fn list_executors(
        &self,
        req: &pb::ListExecutorsRequest,
    ) -> Result<pb::ListExecutorsResponse, Error> {
        self.unary("ListExecutors", req).await
    }

    /// Start an OAuth login for one provider. `provider` is the NAME of a
    /// `providers.toml` entry whose KIND authenticates by login
    /// (`openai-responses-chatgpt`). The answer carries the `login_id` to
    /// complete with, the `authorize_url` to open, and where the provider
    /// sends the browser back: listen on `redirect_port` at `callback_path`
    /// on every host in `redirect_hosts` (the redirect URI is fixed by the
    /// provider's registration), or accept a pasted redirect URL. The
    /// credential is stored against the calling user and never returned;
    /// the daemon holds the tokens. Needs a user credential on the client:
    /// `failed_precondition` when the connection has none, `permission_denied`
    /// for a child's credential. A provider that is unknown, or whose entry
    /// does not login-authenticate, is `invalid_argument`.
    pub async fn begin_provider_login(
        &self,
        req: &pb::BeginProviderLoginRequest,
    ) -> Result<pb::BeginProviderLoginResponse, Error> {
        self.unary("BeginProviderLogin", req).await
    }

    /// Finish the login [`Client::begin_provider_login`] started, handing
    /// back the raw query string the provider redirected to loopback with
    /// (`callback_query`). The answer names the `provider` and the
    /// authenticated `account_id`; the tokens stay in the daemon.
    /// `not_found` for a login id that is unknown, expired, or was begun by
    /// another user: one identical answer for all three, so no caller can
    /// probe which logins exist.
    pub async fn complete_provider_login(
        &self,
        req: &pb::CompleteProviderLoginRequest,
    ) -> Result<pb::CompleteProviderLoginResponse, Error> {
        self.unary("CompleteProviderLogin", req).await
    }

    /// Delete the calling user's stored credential for one provider, so that
    /// provider's login-authenticated kind stops resolving for this user's
    /// children, whose next turn then fails with the re-login error.
    /// `not_found` when the user has no credential stored for that provider
    /// name, whether or not the provider is configured: the delete never
    /// resolves the provider entry, so a login stored under a name removed from
    /// providers.toml can still be cleared.
    pub async fn delete_provider_credential(
        &self,
        req: &pb::DeleteProviderCredentialRequest,
    ) -> Result<pb::DeleteProviderCredentialResponse, Error> {
        self.unary("DeleteProviderCredential", req).await
    }

    /// Start an OAuth login for one direct-url entry of an MCP config file.
    /// `config_path` is an ABSOLUTE path ON THE DAEMON HOST: the daemon reads
    /// that exact file and that exact `mcpServers` entry, so a client on
    /// another machine cannot upload its project config here. `scopes`
    /// overrides what discovery would request; empty asks for the challenged
    /// scopes, else the resource's advertised ones.
    ///
    /// The answer carries the `login_id` to complete with, the `authorize_url`
    /// to open, and where the server sends the browser back: listen on
    /// `redirect_port` at `callback_path` on every host in `redirect_hosts`,
    /// or accept a pasted redirect URL. The grant is stored against the
    /// CALLING USER and is never returned — no token, no client secret and no
    /// callback code crosses this seam. Needs a user credential on the client:
    /// `failed_precondition` when the connection has none, `permission_denied`
    /// for a child's credential. A path the daemon cannot read, an entry it
    /// does not declare, and an entry that cannot log in here (a stdio server,
    /// a `via_executor` server, an entry with its own `Authorization` header)
    /// are all `invalid_argument`. Nothing is prompted during a spawn: an
    /// explicit login is the only way a grant exists.
    pub async fn begin_mcp_login(
        &self,
        req: &pb::BeginMcpLoginRequest,
    ) -> Result<pb::BeginMcpLoginResponse, Error> {
        self.unary("BeginMcpLogin", req).await
    }

    /// Finish one consent round of the login [`Client::begin_mcp_login`]
    /// started, handing back the raw query string the server redirected to
    /// loopback with (`callback_query`, leading `?` optional). A code is single
    /// use: replaying one is `invalid_argument`.
    ///
    /// EXACTLY ONE OUTCOME. When `continuation` is set the login is not
    /// finished — nothing is stored yet, the same `login_id` carries on, and
    /// the continuation is another Begin-shaped descriptor to drive another
    /// round. Only a response with no continuation is a success, and then
    /// `server`, `resource`, `account_id` (empty unless a validated source
    /// names one) and the sorted tool NAMES are set.
    ///
    /// `not_found` for a login id that is unknown, expired, or was begun by
    /// another user: one identical answer for all three, so no caller can
    /// probe which logins exist. A refused consent round, a replayed callback
    /// and a callback that does not match the login's state/issuer are
    /// `invalid_argument`: the login is over and must be started again.
    pub async fn complete_mcp_login(
        &self,
        req: &pb::CompleteMcpLoginRequest,
    ) -> Result<pb::CompleteMcpLoginResponse, Error> {
        self.unary("CompleteMcpLogin", req).await
    }

    /// Delete one of the calling user's stored MCP grants. Two exclusive
    /// forms: `config_path` + `server` resolves the configured direct-url
    /// entry and invalidates its endpoint (which also fences a first login
    /// still in flight), or `resource` names the canonical resource URL
    /// directly and touches no config at all — that is how a grant is removed
    /// once its project file is gone. Passing both, or neither, is
    /// `invalid_argument`.
    ///
    /// A grant the caller does not have is `not_found`. The local invalidation
    /// is what logout means: an upstream revocation that fails does not
    /// restore the grant, and the user's children then get the re-login hint.
    pub async fn delete_mcp_credential(
        &self,
        req: &pb::DeleteMcpCredentialRequest,
    ) -> Result<pb::DeleteMcpCredentialResponse, Error> {
        self.unary("DeleteMcpCredential", req).await
    }
}
